// English lives in the HTML; Chinese comes from /i18n/zh.json (generated by
// tools/site_build.py). Elements opt in with:
//   data-i18n="key"            text content (leaf elements only)
//   data-i18n-html="key"       inner HTML from the site's own dictionary
//   data-i18n-attr="attr:key;attr:key"
const root = document.documentElement;
const KEY = "sc-lang";
const originals = new WeakMap();
let dict = null;
let loading = null;

export function lang() {
  return root.dataset.lang === "zh" ? "zh" : "en";
}

export function t(key, english) {
  if (lang() === "zh" && dict && Object.hasOwn(dict, key)) return dict[key];
  return english;
}

// Pick the right side of an {en, zh} pair from data/games.json.
export function pick(pair) {
  if (pair == null || typeof pair !== "object") return pair ?? "";
  return (lang() === "zh" && pair.zh) || pair.en || "";
}

function load() {
  if (dict) return Promise.resolve(dict);
  loading ||= fetch("/i18n/zh.json")
    .then((response) => {
      if (!response.ok) throw new Error(`zh dictionary returned ${response.status}`);
      return response.json();
    })
    .then((data) => {
      dict = data;
      return dict;
    })
    .catch((error) => {
      loading = null;
      throw error;
    });
  return loading;
}

function remember(el, slot, value) {
  let slots = originals.get(el);
  if (!slots) originals.set(el, (slots = new Map()));
  if (!slots.has(slot)) slots.set(slot, value);
  return slots.get(slot);
}

function lookup(key, english) {
  return lang() === "zh" && dict && Object.hasOwn(dict, key) ? dict[key] : english;
}

function each(scope, selector, fn) {
  if (scope instanceof Element && scope.matches(selector)) fn(scope);
  scope.querySelectorAll(selector).forEach(fn);
}

export function translate(scope = document) {
  each(scope, "[data-i18n]", (el) => {
    const next = lookup(el.dataset.i18n, remember(el, "#text", el.textContent));
    if (el.textContent !== next) el.textContent = next;
  });
  each(scope, "[data-i18n-html]", (el) => {
    const next = lookup(el.dataset.i18nHtml, remember(el, "#html", el.innerHTML));
    if (el.innerHTML !== next) el.innerHTML = next;
  });
  each(scope, "[data-i18n-attr]", (el) => {
    for (const pair of el.dataset.i18nAttr.split(";")) {
      const [attr, key] = pair.split(":").map((part) => part.trim());
      if (!attr || !key) continue;
      const next = lookup(key, remember(el, `@${attr}`, el.getAttribute(attr) ?? ""));
      if (el.getAttribute(attr) !== next) el.setAttribute(attr, next);
    }
  });
}

function syncLangSwitches() {
  const current = lang();
  document.querySelectorAll("[data-lang-set]").forEach((button) => {
    button.setAttribute("aria-pressed", String(button.dataset.langSet === current));
  });
}

export async function setLang(next, { persist = true } = {}) {
  const target = next === "zh" ? "zh" : "en";
  if (persist) {
    try {
      localStorage.setItem(KEY, target);
    } catch {
      /* private mode: the choice lasts for this page only */
    }
  }
  if (target === "zh") {
    try {
      await load();
    } catch (error) {
      console.error(error);
    }
  }
  root.dataset.lang = target;
  root.lang = target === "zh" ? "zh-CN" : "en";
  translate(document);
  syncLangSwitches();
  document.dispatchEvent(new CustomEvent("sc:langchange", { detail: { lang: target } }));
}

export function initI18n() {
  document.addEventListener("click", (event) => {
    const button = event.target.closest("[data-lang-set]");
    if (!button || button.dataset.langSet === lang()) return;
    setLang(button.dataset.langSet);
  });
  syncLangSwitches();
  if (lang() !== "zh") {
    root.classList.remove("i18n-pending");
    return;
  }
  load()
    .then(() => {
      translate(document);
      document.dispatchEvent(new CustomEvent("sc:langchange", { detail: { lang: "zh" } }));
    })
    .catch((error) => console.error(error))
    .finally(() => root.classList.remove("i18n-pending"));
}
